function probe(h, axisSums, lastSample) {
  var axis = axisSums[0] <= axisSums[1] ? 0 : 1;
  var sign = 1;
  if (lastSample && lastSample.limited && lastSample.command) {
    var cv = lastSample.command[axis];
    if (Math.abs(cv) > 1e-9) sign = cv > 0 ? -1 : 1;
  }
  var u = axis === 0 ? [0.1 * sign, 0] : [0, 0.1 * sign];
  return { action: 'move', u: u };
}

function control(state) {
  var tip = state.tip, tg = state.target;
  var ex = tg[0] - tip[0], ey = tg[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(err)) return { action: 'stop', reason: 'non-finite error' };
  if (err <= state.tolerancePx) return { action: 'verify' };
  var h = state.history || [];
  if (state.maxActions && h.length >= state.maxActions) return { action: 'stop', reason: 'action budget reached' };

  var start = h.length > 12 ? h.length - 12 : 0;
  var M = [[0, 0], [0, 0]];
  var D = [[0, 0], [0, 0]];
  var n = 0;
  var axisSums = [0, 0];
  var lastSample = h.length ? h[h.length - 1] : null;
  for (var i = start; i < h.length; i++) {
    var s = h[i];
    if (!s || !s.applied || !s.delta) continue;
    var c = s.applied, d = s.delta;
    if (!isFinite(c[0]) || !isFinite(c[1]) || !isFinite(d[0]) || !isFinite(d[1])) continue;
    axisSums[0] += Math.abs(c[0]);
    axisSums[1] += Math.abs(c[1]);
    if (Math.abs(c[0]) + Math.abs(c[1]) < 1e-6) continue;
    n++;
    for (var p = 0; p < 2; p++) {
      for (var q = 0; q < 2; q++) M[p][q] += c[p] * c[q];
    }
    for (var r = 0; r < 2; r++) {
      for (var j = 0; j < 2; j++) D[r][j] += d[r] * c[j];
    }
  }

  var scale = M[0][0] + M[1][1];
  if (!(scale > 0)) return probe(h, axisSums, lastSample);
  var lam = 1e-6 * scale;
  M[0][0] += lam; M[1][1] += lam;
  var detM = M[0][0] * M[1][1] - M[0][1] * M[1][0];
  var scale2 = M[0][0] + M[1][1];
  if (n < 3 || !(detM > 0.01 * scale2 * scale2)) return probe(h, axisSums, lastSample);

  var Minv = [[M[1][1] / detM, -M[0][1] / detM], [-M[1][0] / detM, M[0][0] / detM]];
  var J = [[0, 0], [0, 0]];
  for (var a = 0; a < 2; a++) {
    for (var b = 0; b < 2; b++) {
      J[a][b] = D[a][0] * Minv[0][b] + D[a][1] * Minv[1][b];
    }
  }
  var detJ = J[0][0] * J[1][1] - J[0][1] * J[1][0];
  if (!isFinite(detJ) || Math.abs(detJ) < 1e-6) return probe(h, axisSums, lastSample);

  var c0 = (J[1][1] * ex - J[0][1] * ey) / detJ;
  var c1 = (-J[1][0] * ex + J[0][0] * ey) / detJ;
  if (!isFinite(c0) || !isFinite(c1)) return probe(h, axisSums, lastSample);

  var m = Math.max(Math.abs(c0), Math.abs(c1));
  if (m > 0.1) { c0 = c0 * 0.1 / m; c1 = c1 * 0.1 / m; }
  return { action: 'move', u: [c0, c1] };
}

function control(state) {
  var tip = state.tip;
  var target = state.target;
  var LIM = 0.1;
  var ex = target[0] - tip[0];
  var ey = target[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);

  if (state.maxActions !== undefined && state.maxActions !== null && state.step >= state.maxActions) {
    return { action: "stop", reason: "action budget reached" };
  }
  if (err <= state.tolerancePx) {
    return { action: "verify" };
  }

  var h = state.history || [];

  // 是否連續多步幾乎不動（可能貼近行程邊界或 Jacobian 失準）
  var stuck = false;
  if (h.length >= 3) {
    stuck = true;
    for (var j = h.length - 3; j < h.length; j++) {
      var r = h[j];
      if (!r || !r.delta || !r.applied) { stuck = false; break; }
      var mag = Math.sqrt(r.delta[0] * r.delta[0] + r.delta[1] * r.delta[1]);
      var cmag = Math.abs(r.applied[0]) + Math.abs(r.applied[1]);
      if (cmag === 0 || mag >= 0.5) { stuck = false; break; }
    }
  }

  var m00 = 0, m01 = 0, m11 = 0;
  var b00 = 0, b01 = 0, b10 = 0, b11 = 0;
  var n = 0;
  for (var i = 0; i < h.length; i++) {
    var rec = h[i];
    if (!rec || !rec.applied || !rec.delta) continue;
    var c0 = rec.applied[0], c1 = rec.applied[1];
    var d0 = rec.delta[0], d1 = rec.delta[1];
    if (!isFinite(c0) || !isFinite(c1) || !isFinite(d0) || !isFinite(d1)) continue;
    if (c0 === 0 && c1 === 0) continue;
    m00 += c0 * c0; m01 += c0 * c1; m11 += c1 * c1;
    b00 += d0 * c0; b01 += d0 * c1;
    b10 += d1 * c0; b11 += d1 * c1;
    n++;
  }

  // 小量正則化，避免奇異
  var lam = 1e-5;
  m00 += lam; m11 += lam;

  // 探測序列：包含正負兩個方向，避免只在單側被行程限制卡住
  var pats = [[LIM, 0], [0, LIM], [-LIM, 0], [0, -LIM]];
  var probeIdx = h.length % 4;
  if (stuck) {
    probeIdx = (probeIdx + 2) % 4;
  }
  var u = null;

  if (!stuck && n >= 2) {
    var detM = m00 * m11 - m01 * m01;
    var traceM = m00 + m11;
    if (traceM > 0 && Math.abs(detM) > 1e-6 * traceM * traceM) {
      var inv00 = m11 / detM, inv01 = -m01 / detM;
      var inv10 = -m01 / detM, inv11 = m00 / detM;
      var J00 = b00 * inv00 + b01 * inv10;
      var J01 = b00 * inv01 + b01 * inv11;
      var J10 = b10 * inv00 + b11 * inv10;
      var J11 = b10 * inv01 + b11 * inv11;
      var detJ = J00 * J11 - J01 * J10;
      var scaleJ = Math.max(Math.abs(J00), Math.abs(J01), Math.abs(J10), Math.abs(J11), 1e-12);
      if (isFinite(detJ) && Math.abs(detJ) > 1e-4 * scaleJ * scaleJ) {
        var iD = 1 / detJ;
        var u0 = (J11 * ex - J01 * ey) * iD;
        var u1 = (-J10 * ex + J00 * ey) * iD;
        if (isFinite(u0) && isFinite(u1)) {
          var mx = Math.max(Math.abs(u0), Math.abs(u1));
          if (mx > 0) {
            var s = Math.min(1, err / 25);
            var k = LIM / mx;
            if (k > 1) k = 1;
            u = [u0 * k * s, u1 * k * s];
          }
        }
      }
    }
  }

  if (u === null) {
    u = pats[probeIdx];
  }

  var a = Math.max(-LIM, Math.min(LIM, u[0]));
  var b = Math.max(-LIM, Math.min(LIM, u[1]));
  if (!isFinite(a) || !isFinite(b)) {
    return { action: "stop", reason: "non-finite control output" };
  }
  return { action: "move", u: [a, b] };
}

function clip(v) { if (v > 0.1) return 0.1; if (v < -0.1) return -0.1; return v; }

function probe(n) {
  var k = n % 4;
  if (k === 0) return [0.08, 0];
  if (k === 1) return [-0.08, 0];
  if (k === 2) return [0, 0.08];
  return [0, -0.08];
}

function control(state) {
  var tip = state.tip, target = state.target;
  var ex = target[0] - tip[0], ey = target[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(err)) return { action: 'stop', reason: 'non-finite error' };
  if (err <= state.tolerancePx) return { action: 'verify' };

  var h = state.history || [];
  var n = h.length;
  var start = n > 40 ? n - 40 : 0;

  // 上一步若被行程限制，改為探測以避免卡在邊界
  if (n > 0 && h[n - 1].limited) return { action: 'move', u: probe(n) };

  var M = [[0, 0], [0, 0]];
  var R = [[0, 0], [0, 0]];
  for (var i = start; i < n; i++) {
    var c = h[i].applied, d = h[i].delta;
    if (!c || !d || !isFinite(c[0]) || !isFinite(c[1]) || !isFinite(d[0]) || !isFinite(d[1])) continue;
    for (var a = 0; a < 2; a++) {
      for (var b = 0; b < 2; b++) M[a][b] += c[a] * c[b];
      for (var j = 0; j < 2; j++) R[a][j] += c[a] * d[j];
    }
  }

  var det = M[0][0] * M[1][1] - M[0][1] * M[1][0];
  var scale = M[0][0] + M[1][1];
  if (M[0][0] < 1e-4) return { action: 'move', u: probe(n) };
  if (M[1][1] < 1e-4) return { action: 'move', u: probe(n) };
  if (!(Math.abs(det) > 1e-6 * scale * scale)) return { action: 'move', u: probe(n) };

  var Minv = [[M[1][1] / det, -M[0][1] / det], [-M[1][0] / det, M[0][0] / det]];
  var J = [[0, 0], [0, 0]];
  for (var jj = 0; jj < 2; jj++) {
    for (var aa = 0; aa < 2; aa++) {
      J[jj][aa] = R[0][jj] * Minv[0][aa] + R[1][jj] * Minv[1][aa];
    }
  }

  var A00 = J[0][0] * J[0][0] + J[0][1] * J[0][1];
  var A01 = J[0][0] * J[1][0] + J[0][1] * J[1][1];
  var A11 = J[1][0] * J[1][0] + J[1][1] * J[1][1];
  var lam = 1e-3 * (A00 + A11) + 1e-9;
  A00 += lam; A11 += lam;
  var adet = A00 * A11 - A01 * A01;
  if (!(Math.abs(adet) > 1e-12)) return { action: 'move', u: probe(n) };
  var w0 = (A11 * ex - A01 * ey) / adet;
  var w1 = (-A01 * ex + A00 * ey) / adet;
  var u0 = J[0][0] * w0 + J[1][0] * w1;
  var u1 = J[0][1] * w0 + J[1][1] * w1;
  if (!isFinite(u0) || !isFinite(u1)) return { action: 'move', u: probe(n) };

  var m = Math.max(Math.abs(u0), Math.abs(u1));
  if (m === 0) return { action: 'move', u: probe(n) };
  var f;
  if (err > 30) {
    f = 0.1 / m;
  } else {
    f = Math.min(0.1 / m, 0.6);
  }
  var v0 = clip(Math.round(u0 * f * 10000) / 10000);
  var v1 = clip(Math.round(u1 * f * 10000) / 10000);
  return { action: 'move', u: [v0, v1] };
}

function control(state) {
  var lim = (state && state.inputLimit) ? state.inputLimit : 0.1;
  var tol = (state && state.tolerancePx) ? state.tolerancePx : 7;
  var tip = state.tip;
  var tgt = state.target;
  var ex = tgt[0] - tip[0];
  var ey = tgt[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(err)) {
    return { action: 'stop', reason: 'non-finite error' };
  }
  if (err <= tol) {
    return { action: 'verify' };
  }

  var h = state.history || [];
  var n = h.length;
  var s00 = 0, s01 = 0, s11 = 0;
  var m00 = 0, m01 = 0, m10 = 0, m11 = 0;
  var usable = 0;
  var stuck = [false, false];
  var lastSign = [1, 1];
  for (var i = 0; i < n; i++) {
    var rec = h[i];
    var c = rec.applied || rec.command;
    var cmd = rec.command;
    var d = rec.delta;
    if (cmd && c && cmd.length >= 2 && c.length >= 2) {
      for (var k = 0; k < 2; k++) {
        if (isFinite(cmd[k]) && Math.abs(cmd[k]) > 1e-6) {
          lastSign[k] = cmd[k] > 0 ? 1 : -1;
          stuck[k] = Math.abs(c[k]) < 1e-6;
        }
      }
    }
    if (!c || !d || c.length < 2 || d.length < 2) continue;
    var c0 = c[0], c1 = c[1], d0 = d[0], d1 = d[1];
    if (!isFinite(c0) || !isFinite(c1) || !isFinite(d0) || !isFinite(d1)) continue;
    if (Math.abs(c0) + Math.abs(c1) < 1e-6) continue;
    var w = 1 + (i + 1) / Math.max(1, n);
    usable++;
    s00 += w * c0 * c0;
    s01 += w * c0 * c1;
    s11 += w * c1 * c1;
    m00 += w * d0 * c0;
    m01 += w * d0 * c1;
    m10 += w * d1 * c0;
    m11 += w * d1 * c1;
  }

  var sdet = s00 * s11 - s01 * s01;
  var illCond = usable < 2 || s00 <= 0 || s11 <= 0 || sdet <= 1e-4 * s00 * s11;
  if (illCond) {
    var pick;
    if (s00 < s11) pick = 0;
    else if (s11 < s00) pick = 1;
    else pick = n % 2;
    if (stuck[pick] && !stuck[1 - pick]) pick = 1 - pick;
    var sg = stuck[pick] ? -lastSign[pick] : lastSign[pick];
    var pu = [0, 0];
    pu[pick] = sg * lim;
    return { action: 'move', u: [pu[0], pu[1]] };
  }

  var inv00 = s11 / sdet, inv01 = -s01 / sdet, inv11 = s00 / sdet;
  var j00 = m00 * inv00 + m01 * inv01;
  var j01 = m00 * inv01 + m01 * inv11;
  var j10 = m10 * inv00 + m11 * inv01;
  var j11 = m10 * inv01 + m11 * inv11;
  if (!isFinite(j00) || !isFinite(j01) || !isFinite(j10) || !isFinite(j11)) {
    return { action: 'move', u: [lim, 0] };
  }

  var a00 = j00 * j00 + j10 * j10;
  var a01 = j00 * j01 + j10 * j11;
  var a11 = j01 * j01 + j11 * j11;
  var mu = 1e-9 * (a00 + a11) + 1e-12;
  a00 += mu;
  a11 += mu;
  var b0 = j00 * ex + j10 * ey;
  var b1 = j01 * ex + j11 * ey;
  var adet = a00 * a11 - a01 * a01;
  if (!isFinite(adet) || Math.abs(adet) < 1e-18) {
    return { action: 'move', u: [lim, 0] };
  }
  var u0 = (a11 * b0 - a01 * b1) / adet;
  var u1 = (-a01 * b0 + a00 * b1) / adet;
  if (!isFinite(u0) || !isFinite(u1)) {
    return { action: 'move', u: [lim, 0] };
  }

  // block commands pushing into a channel that is at its travel limit
  if (stuck[0] && u0 * lastSign[0] > 0) u0 = 0;
  if (stuck[1] && u1 * lastSign[1] > 0) u1 = 0;

  var mx = Math.max(Math.abs(u0), Math.abs(u1));
  if (mx === 0) {
    var fb = [0, 0];
    if (stuck[0]) fb[0] = -lastSign[0] * lim;
    else if (stuck[1]) fb[1] = -lastSign[1] * lim;
    else fb[0] = lim;
    return { action: 'move', u: [fb[0], fb[1]] };
  }
  if (mx > lim) {
    var sc = lim / mx;
    u0 *= sc;
    u1 *= sc;
    mx = lim;
  }
  var gain = (err < 3 * tol) ? 0.5 : 1;
  u0 *= gain;
  u1 *= gain;
  mx = Math.max(Math.abs(u0), Math.abs(u1));
  if (mx < 0.01) {
    var s2 = 0.01 / mx;
    u0 *= s2;
    u1 *= s2;
  }
  var q0 = Math.round(u0 * 10000) / 10000;
  var q1 = Math.round(u1 * 10000) / 10000;
  if (q0 > lim) q0 = lim;
  if (q0 < -lim) q0 = -lim;
  if (q1 > lim) q1 = lim;
  if (q1 < -lim) q1 = -lim;
  return { action: 'move', u: [q0, q1] };
}

function control(state) {
  var LIM = 0.1;
  var tip = state.tip;
  var tgt = state.target;
  if (!tip || !tgt || !isFinite(tip[0]) || !isFinite(tip[1]) || !isFinite(tgt[0]) || !isFinite(tgt[1])) {
    return { action: "stop", reason: "invalid tip or target" };
  }
  var ex = tgt[0] - tip[0];
  var ey = tgt[1] - tip[1];
  var e = Math.sqrt(ex * ex + ey * ey);
  var tol = (typeof state.tolerancePx === "number") ? state.tolerancePx : 7;
  if (e <= tol) {
    return { action: "verify" };
  }
  var h = state.history || [];
  var start = Math.max(0, h.length - 16);
  var g00 = 0, g01 = 0, g11 = 0;
  var h00 = 0, h01 = 0, h10 = 0, h11 = 0;
  for (var i = start; i < h.length; i++) {
    var ent = h[i];
    if (!ent || !ent.command || !ent.delta) continue;
    var a = ent.command[0], b = ent.command[1];
    var dx = ent.delta[0], dy = ent.delta[1];
    if (!isFinite(a) || !isFinite(b) || !isFinite(dx) || !isFinite(dy)) continue;
    g00 += a * a;
    g01 += a * b;
    g11 += b * b;
    h00 += a * dx;
    h01 += a * dy;
    h10 += b * dx;
    h11 += b * dy;
  }
  // Excitation check: probe channels that have not been excited yet
  if (g00 < 1e-6 && g11 < 1e-6) {
    return { action: "move", u: [LIM, 0] };
  }
  if (g00 < 1e-6) {
    return { action: "move", u: [LIM, 0] };
  }
  if (g11 < 1e-6) {
    return { action: "move", u: [0, LIM] };
  }
  var det = g00 * g11 - g01 * g01;
  if (!(det > 1e-3 * g00 * g11)) {
    // Near-collinear past commands: excite the weaker channel
    if (g00 <= g11) {
      return { action: "move", u: [LIM, 0] };
    }
    return { action: "move", u: [0, LIM] };
  }
  // W = Ginv * H, where delta ~= W^T * command
  var i00 = g11 / det, i01 = -g01 / det, i10 = -g01 / det, i11 = g00 / det;
  var w00 = i00 * h00 + i01 * h10;
  var w01 = i00 * h01 + i01 * h11;
  var w10 = i10 * h00 + i11 * h10;
  var w11 = i10 * h01 + i11 * h11;
  // J = W^T : output r from input c
  var J00 = w00, J01 = w10, J10 = w01, J11 = w11;
  // M = J J^T
  var m00 = J00 * J00 + J01 * J01;
  var m01 = J00 * J10 + J01 * J11;
  var m11 = J10 * J10 + J11 * J11;
  var tr = m00 + m11;
  var lam = 1e-6 * (tr > 0 ? tr : 1);
  m00 += lam;
  m11 += lam;
  var md = m00 * m11 - m01 * m01;
  if (!(Math.abs(md) > 1e-18)) {
    return { action: "move", u: [LIM, 0] };
  }
  // y = (M)^{-1} e
  var y0 = (m11 * ex - m01 * ey) / md;
  var y1 = (-m01 * ex + m00 * ey) / md;
  // x = J^T y
  var x0 = J00 * y0 + J10 * y1;
  var x1 = J01 * y0 + J11 * y1;
  if (!isFinite(x0) || !isFinite(x1)) {
    return { action: "move", u: [LIM, 0] };
  }
  var mx = Math.max(Math.abs(x0), Math.abs(x1));
  if (mx < 1e-12) {
    return { action: "move", u: [LIM, 0] };
  }
  var s = 1;
  if (mx > LIM) {
    s = LIM / mx;
  }
  if (e < 20) {
    s = s * 0.7;
  }
  var u0 = x0 * s;
  var u1 = x1 * s;
  if (u0 > LIM) u0 = LIM;
  if (u0 < -LIM) u0 = -LIM;
  if (u1 > LIM) u1 = LIM;
  if (u1 < -LIM) u1 = -LIM;
  return { action: "move", u: [u0, u1] };
}

function control(state) {
  var tip = state && state.tip;
  var tgt = state && state.target;
  if (!tip || !tgt || tip.length !== 2 || tgt.length !== 2) return { action: "stop", reason: "bad state" };
  var ex = tgt[0] - tip[0];
  var ey = tgt[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(err)) return { action: "stop", reason: "non-finite error" };
  if (err <= state.tolerancePx) return { action: "verify" };

  var h = state.history || [];
  var n = h.length;

  // Weighted least squares delta ~= J * applied (recent samples weigh more)
  var lam = 1e-6;
  var a00 = lam, a01 = 0, a11 = lam;
  var bx0 = 0, bx1 = 0, by0 = 0, by1 = 0;
  var c0 = 0, c1 = 0;
  for (var i = 0; i < n; i++) {
    var r = h[i];
    if (!r || !r.applied || !r.delta) continue;
    var a0 = r.applied[0], a1 = r.applied[1];
    var dx = r.delta[0], dy = r.delta[1];
    if (!isFinite(a0) || !isFinite(a1) || !isFinite(dx) || !isFinite(dy)) continue;
    var w = 1 + i / Math.max(1, n);
    a00 += w * a0 * a0;
    a01 += w * a0 * a1;
    a11 += w * a1 * a1;
    bx0 += w * dx * a0;
    bx1 += w * dx * a1;
    by0 += w * dy * a0;
    by1 += w * dy * a1;
    if (Math.abs(a0) > 0.02) c0++;
    if (Math.abs(a1) > 0.02) c1++;
  }

  // Detect channels blocked at travel limit from the most recent sample
  var blocked = [0, 0];
  if (n > 0 && h[n - 1] && h[n - 1].command && h[n - 1].applied) {
    var last = h[n - 1];
    for (var k = 0; k < 2; k++) {
      var cmd = last.command[k], app = last.applied[k];
      if (typeof cmd === "number" && typeof app === "number" && isFinite(cmd) && isFinite(app)) {
        if (cmd !== 0 && Math.abs(app) < 0.5 * Math.abs(cmd)) blocked[k] = cmd > 0 ? 1 : -1;
      }
    }
  }

  // Probe when a channel is not yet sufficiently excited
  if (c0 < 2 || c1 < 2 || n < 2) {
    var ch = (c0 <= c1) ? 0 : 1;
    var s = blocked[ch] !== 0 ? -blocked[ch] : 1;
    var pu = [0, 0];
    pu[ch] = 0.1 * s;
    return { action: "move", u: pu };
  }

  var det = a00 * a11 - a01 * a01;
  if (!(det > 1e-12) || !isFinite(det)) {
    var pc = (c0 <= c1) ? 0 : 1;
    var pv = [0, 0];
    pv[pc] = (blocked[pc] !== 0 ? -blocked[pc] : 1) * 0.1;
    return { action: "move", u: pv };
  }

  var jx0 = (a11 * bx0 - a01 * bx1) / det;
  var jx1 = (-a01 * bx0 + a00 * bx1) / det;
  var jy0 = (a11 * by0 - a01 * by1) / det;
  var jy1 = (-a01 * by0 + a00 * by1) / det;

  // Minimum-norm solution of J u = e: u = J^T (J J^T)^-1 e
  var g00 = jx0 * jx0 + jx1 * jx1 + 1e-9;
  var g01 = jx0 * jy0 + jx1 * jy1;
  var g11 = jy0 * jy0 + jy1 * jy1 + 1e-9;
  var gdet = g00 * g11 - g01 * g01;
  if (!(Math.abs(gdet) > 1e-18) || !isFinite(gdet)) {
    var pq = (c0 <= c1) ? 0 : 1;
    var pw = [0, 0];
    pw[pq] = (blocked[pq] !== 0 ? -blocked[pq] : 1) * 0.1;
    return { action: "move", u: pw };
  }
  var z0 = (g11 * ex - g01 * ey) / gdet;
  var z1 = (-g01 * ex + g00 * ey) / gdet;
  var u0 = jx0 * z0 + jy0 * z1;
  var u1 = jx1 * z0 + jy1 * z1;

  // If a channel is blocked at its limit in the commanded direction, move only the other channel
  var bU = [u0, u1];
  var anyBlocked = false;
  for (var b = 0; b < 2; b++) {
    if (blocked[b] !== 0 && bU[b] * blocked[b] > 0) {
      anyBlocked = true;
      var o = 1 - b;
      var col0 = (o === 0) ? jx0 : jx1;
      var col1 = (o === 0) ? jy0 : jy1;
      var den = col0 * col0 + col1 * col1;
      var uo = 0;
      if (den > 1e-12) uo = (ex * col0 + ey * col1) / den;
      var uf = [0, 0];
      uf[b] = 0;
      uf[o] = uo;
      bU = uf;
    }
  }
  u0 = bU[0];
  u1 = bU[1];

  u0 *= 0.8;
  u1 *= 0.8;
  if (!isFinite(u0) || !isFinite(u1)) {
    return { action: "move", u: [0.1, 0] };
  }
  var m = Math.max(Math.abs(u0), Math.abs(u1));
  if (m < 1e-6) {
    // Model gives no usable motion; probe the less-excited channel
    var pp = (c0 <= c1) ? 0 : 1;
    var pr = [0, 0];
    pr[pp] = (blocked[pp] !== 0 ? -blocked[pp] : 1) * 0.1;
    return { action: "move", u: pr };
  }
  if (m > 0.1) {
    u0 = u0 * 0.1 / m;
    u1 = u1 * 0.1 / m;
  }
  return { action: "move", u: [u0, u1] };
}
